export type Strings = { [K in keyof typeof STR_TABLE.en]: string };
export type Extra = typeof EXTRA_TABLE.en;

export const STR: Record<LangCode, Strings> = STR_TABLE;
export const EXTRA: Record<LangCode, Extra> = EXTRA_TABLE;

export const LANG_ORDER: LangCode[] = ['hi', 'kn', 'ta', 'te', 'en'];
export const DEFAULT_LANG: LangCode = 'hi';

/** An all-blank `Strings`, used as the English second line when English is selected. */
export const BLANK: Strings = Object.fromEntries(Object.keys(STR.en).map((k) => [k, ''])) as Strings;
